INSERT INTO ht_affiche (id,title,affiche_type,type,url,is_show,createtime,`describe`,content,image,publish_time,updatetime,affiche_type_id,collection_ids,`read`,sort,status,top,is_wxpusher,image_type) VALUES (23,'活动 | 《今晚吃鸡》资格合成活动今日开启！','', '1','',1,1794109439,'','<p style="text-wrap-mode:wrap;"><span style="font-size:16px;">尊敬的火兔用户：</span></p><p style="text-wrap-mode:wrap;"><span style="font-size:16px;"><br /></span></p><p style="text-wrap-mode:wrap;"><span style="font-size:16px;">您好！</span></p><br style="text-wrap-mode:wrap;" /><div style="text-wrap-mode:wrap;text-align:center;">平台将开启《今晚吃鸡》资格合成活动！</div><br style="text-wrap-mode:wrap;" /><span style="text-wrap-mode:wrap;">合成资格：</span><br style="text-wrap-mode:wrap;" /><span style="text-wrap-mode:wrap;">每持有</span><span style="text-wrap-mode:wrap;color:#E53333;">《大吉大利》*5</span><span style="text-wrap-mode:wrap;">的用户，即可获得</span><span style="text-wrap-mode:wrap;color:#E53333;">1次《<span style="text-align:center;">今晚吃鸡</span>》专属合成资格</span><span style="text-wrap-mode:wrap;">，资格权益可叠加；</span><br style="text-wrap-mode:wrap;" /><br style="text-wrap-mode:wrap;" /><span style="text-wrap-mode:wrap;">合成材料：</span><br style="text-wrap-mode:wrap;" /><span style="text-wrap-mode:wrap;">每拥有1次《</span><span style="text-wrap-mode:wrap;text-align:center;">今晚吃鸡</span><span style="text-wrap-mode:wrap;">》专属合成资格的用户，即可消耗</span><span style="text-wrap-mode:wrap;color:#E53333;">《大吉大利》*3</span><span style="text-wrap-mode:wrap;">合成为</span><span style="text-wrap-mode:wrap;color:#E53333;">《<span style="text-align:center;">今晚吃鸡</span>》*1</span><span style="text-wrap-mode:wrap;">，本通道最大合成次数为1000次，可多次合成。</span><br style="text-wrap-mode:wrap;" /><br style="text-wrap-mode:wrap;" /><span style="text-wrap-mode:wrap;">故本次《</span><span style="text-wrap-mode:wrap;text-align:center;">今晚吃鸡</span><span style="text-wrap-mode:wrap;">》总发行量为</span><span style="text-wrap-mode:wrap;color:#E53333;">1000份</span><span style="text-wrap-mode:wrap;">，需要收藏或寄售的用户可前往市场进行交易。</span><br style="text-wrap-mode:wrap;" /><br style="text-wrap-mode:wrap;" /><span style="text-wrap-mode:wrap;">1、快照时间：</span><span style="text-wrap-mode:wrap;color:#E53333;">2026年11月8日12:30-12:50</span><br style="text-wrap-mode:wrap;" /><span style="text-wrap-mode:wrap;">2、活动时间：</span><span style="text-wrap-mode:wrap;color:#E53333;">2026年11月8日13:00-14:00</span><br style="text-wrap-mode:wrap;" /><p style="text-wrap-mode:wrap;">3、最终流通份数将以实际为准。</p><p style="text-wrap-mode:wrap;">4、《今晚吃鸡》将于24小时内开放寄售。</p><p style="text-wrap-mode:wrap;text-align:center;"><img src="https://img.hnyiqin.asia/uploads/20261108/c125ef4fa80e2c6e6a3fe923af9d72b8.png" alt="" /></p><p style="text-wrap-mode:wrap;"><div style="text-align:right;">火兔平台</div><div style="text-align:right;">2026年11月8日</div></p>','',1794109439,1794109439,8,'',0,0,1,0,2,NULL) ON DUPLICATE KEY UPDATE title=VALUES(title), content=VALUES(content), `describe`=VALUES(`describe`), publish_time=VALUES(publish_time), affiche_type_id=VALUES(affiche_type_id), updatetime=VALUES(updatetime);
